export function getGuideBySlug(slug: string): GuidePost | undefined {
  return GUIDE_POSTS.find((post) => post.slug === slug);
}

export function getAllGuideSlugs(): string[] {
  return GUIDE_POSTS.map((post) => post.slug);
}
